def name_operands(region,address,operation):
 if region=='D3D' and address==0xE0C5:
  for old,new in (('(#CE8C)','(@PreviewPrices.Karen)'),('LD HL, #CECE','LD HL, @PreviewPrices.Heading'),('LD HL, #CE40','LD HL, @PreviewPrices.Dominion'),('LD HL, #CE99','LD HL, @PreviewPrices.Fervest'),('CALL #BD08','CALL @Station.PrintText.Entry'),('CALL #A380','CALL @Station.SkipCrRecords.Entry'),('CALL #A36E','CALL @Station.PrintAfterCR.Entry'),('(#E148)','(@D3DPreviewState.BaseOperand)'),('(#6320)','(@TextWindow.CursorX)'),('(#6321)','(@TextWindow.CursorY)'),('LD A, #0A','LD A, @TextConst.LineFeed'),('LD (HL), #0A','LD (HL), @TextConst.LineFeed'),('LD A, #0D','LD A, @TextConst.CarriageReturn'),('LD HL, #0800','LD HL, @PreviewPriceConst.HeadingCursor'),('LD HL, #1800','LD HL, @PreviewPriceConst.BodyCursor'),('CP #06','CP @PreviewPriceConst.KarenIndex'),('SUB #18','SUB @PreviewPriceConst.BodyY'),('AND #1F','AND @RowSelectConst.RowMask')):operation=operation.replace(old,new)
  for (r,a),label in LABELS.items():operation=operation.replace('#'+format(a,'04X'),'@D3D.DrawPreviewPrices.'+label)
 if region=='Station' and address==0x67E0:operation=operation.replace('CALL #E0C5','CALL @D3D.DrawPreviewPrices.Entry')
 return operation
